const reduced=matchMedia('(prefers-reduced-motion: reduce)');
class AnimatedNumber{
 constructor(name){this.name=name;this.block=root.querySelector('[data-number-block="'+name+'"]');this.output=root.querySelector('[data-number="'+name+'"]');this.status=root.querySelector('[data-number-status="'+name+'"]');this.visible=false;this.frame=0;this.key='';this.pending=true;}
 stop(){cancelAnimationFrame(this.frame);this.frame=0;}
 select(key,config){if(this.key===key)return;this.stop();this.key=key;this.config=config;this.pending=true;this.output.textContent=config.to.toLocaleString('en-US');this.status.textContent='';if(this.visible)this.run();}
 finish(){this.stop();this.output.textContent=this.config.to.toLocaleString('en-US');this.status.textContent=this.config.label+' '+this.config.to.toLocaleString('en-US')+' '+this.config.unit;this.pending=false;}
 run(){this.stop();if(!this.config)return;if(reduced.matches){this.finish();return;}const config=this.config,start=performance.now();this.status.textContent='';this.output.textContent=config.from.toLocaleString('en-US');this.pending=false;const tick=now=>{const t=Math.min(1,(now-start)/2000),ease=1-Math.pow(1-t,3);this.output.textContent=Math.round(config.from+(config.to-config.from)*ease).toLocaleString('en-US');if(t<1)this.frame=requestAnimationFrame(tick);else this.finish();};this.frame=requestAnimationFrame(tick);}
 visibility(visible){this.visible=visible;if(visible&&this.pending)this.run();if(!visible&&this.frame){this.stop();this.pending=true;this.output.textContent=this.config.to.toLocaleString('en-US');}}
}
const numbers={growth:new AnimatedNumber('growth'),marketingViews:new AnimatedNumber('marketingViews'),marketingComments:new AnimatedNumber('marketingComments'),topup:new AnimatedNumber('topup')};
const numberObserver=new IntersectionObserver(entries=>entries.forEach(e=>numbers[e.target.dataset.numberBlock].visibility(e.isIntersecting)),{threshold:.3});Object.values(numbers).forEach(n=>numberObserver.observe(n.block));
const simLoop=root.querySelector('.v6-sim-loop'),simTrack=root.querySelector('.v6-sim-track');
const simGroup=document.createElement('div');simGroup.className='v6-sim-group';
[['simSocial','ซิม AIS Super Social'],['simZeed','ซิม AIS ZEED'],['aisSim','ซิม AIS The One']].forEach(([key,alt])=>{const img=document.createElement('img');img.src=assets[key];img.alt=alt;if(key==='aisSim'){const crop=document.createElement('div');crop.className='v5-sim-crop';crop.append(img);simGroup.append(crop);}else simGroup.append(img);});
simTrack.append(simGroup);const duplicate=simGroup.cloneNode(true);duplicate.setAttribute('aria-hidden','true');duplicate.querySelectorAll('img').forEach(i=>i.alt='');simTrack.append(duplicate);
let simVisible=false,simHover=false,simFocus=false;
const updateSim=()=>{const paused=state.simPaused||simHover||simFocus||!simVisible||state.journey!==2||state.page!=='home'||reduced.matches;simLoop.classList.toggle('is-running',!paused);simLoop.setAttribute('aria-pressed',String(state.simPaused));simLoop.setAttribute('aria-label',state.simPaused?'เริ่มภาพซิมเคลื่อนอีกครั้ง':'หยุดภาพซิมที่เคลื่อนอยู่');};
new IntersectionObserver(entries=>{simVisible=entries[0].isIntersecting;updateSim();},{threshold:.2}).observe(simLoop);
simLoop.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){simHover=true;updateSim();}});simLoop.addEventListener('pointerleave',()=>{simHover=false;updateSim();});
simLoop.addEventListener('focus',()=>{simFocus=simLoop.matches(':focus-visible');updateSim();});simLoop.addEventListener('blur',()=>{simFocus=false;updateSim();});simLoop.addEventListener('click',()=>{state.simPaused=!state.simPaused;updateSim();save();});
const posts=['ซื้อ 1 แถม 1','SIM Flash Sale','Black Friday','10.10 ดีลคู่ร้าน','เปิดเทอม พร้อมเรียน','New Arrival รุ่นใหม่มาแล้ว','Mid Month Deal','Payday Sale','Weekend Special'];let lastPostTrigger=null;
